// ── AI Token Usage Logger — Cost Calculator ──
// Accepts POST body: { provider, model, prompt_tokens, completion_tokens,
//                      workflow_name, node_name, status, metadata }

const PRICE = {
  // OpenAI
  'gpt-4o':                       { i: 0.0025,   o: 0.01    },
  'gpt-4o-mini':                  { i: 0.00015,  o: 0.0006  },
  'gpt-4-turbo':                  { i: 0.01,     o: 0.03    },
  'gpt-3.5-turbo':                { i: 0.0005,   o: 0.0015  },
  // Anthropic
  'claude-3-5-sonnet-20241022':   { i: 0.003,    o: 0.015   },
  'claude-3-5-haiku-20241022':    { i: 0.0008,   o: 0.004   },
  'claude-3-opus-20240229':       { i: 0.015,    o: 0.075   },
  'claude-3-haiku-20240307':      { i: 0.00025,  o: 0.00125 },
  // Google
  'gemini-1.5-pro':               { i: 0.00125,  o: 0.005   },
  'gemini-1.5-flash':             { i: 0.000075, o: 0.0003  },
  'gemini-2.0-flash':             { i: 0,        o: 0       },
  // Groq
  'llama-3.3-70b-versatile':      { i: 0.00059,  o: 0.00079 },
  'llama-3.1-8b-instant':         { i: 0.00005,  o: 0.00008 },
  'mixtral-8x7b-32768':           { i: 0.00024,  o: 0.00024 },
};

const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.body || item.json || {};

  const provider         = (body.provider || 'unknown').toLowerCase();
  const model            = body.model || 'unknown';
  const prompt_tokens    = parseInt(body.prompt_tokens)    || 0;
  const completion_tokens = parseInt(body.completion_tokens) || 0;
  const total_tokens     = prompt_tokens + completion_tokens;
  const workflow_name    = body.workflow_name || null;
  const node_name        = body.node_name    || null;
  const status           = body.status       || 'success';
  const metadata         = body.metadata     || {};

  // Cost calculation (USD per 1K tokens)
  const p = PRICE[model] || { i: 0, o: 0 };
  const cost_usd = (prompt_tokens / 1000 * p.i) + (completion_tokens / 1000 * p.o);

  results.push({
    json: {
      supabase_url: item.json.supabase_url,
      supabase_key: item.json.supabase_key,
      record: {
        provider,
        model,
        prompt_tokens,
        completion_tokens,
        total_tokens,
        cost_usd: parseFloat(cost_usd.toFixed(8)),
        workflow_name,
        node_name,
        status,
        metadata,
      }
    }
  });
}

return results;
